import React, { useState } from 'react'

export default function TextForm(props) {

  const [text, setText] = useState("");

  const handleUpClick = () => {
    setText(text.toUpperCase());
    props.showAlert("Converted to UpperCase!", "success");
  }

  const handleClick = () => {
    setText(text.toLowerCase());
    props.showAlert("Converted to LowerCase!", "success");
  }

  const handleClearClick = () => {
    setText("");
    props.showAlert("Text Cleared!", "success");
  }

  const handleCopy = () => {
    navigator.clipboard.writeText(text);
    props.showAlert("Text Copied to clipboard!", "success");
  }

  const handleExtraSpaces = () => {
    setText(text.split(/[ ]+/).join(" ").trim());
    props.showAlert("Extra Spaces Removed!", "success");
  }

  const handleReverse = () => {
    setText(text.split("").reverse().join(""));
    props.showAlert("Text Reversed!", "success");
  }

  const handleRemoveNumbers = () => {
    setText(text.replace(/[0-9]/g, ''));
    props.showAlert("Numbers Removed!", "success");
  }

  const handleCapitalize = () => {
    setText(text.split(" ").map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()).join(" "));
    props.showAlert("Text Capitalized!", "success");
  }

  const handleOnChange = (event) => {
    setText(event.target.value);
  }

  // Search highlight karne ka logic
  const getHighlightedText = () => {
    if (!props.searchQuery || props.searchQuery.trim() === '') {
      return <p>{text || "Enter something in the textbox above to preview it here"}</p>;
    }
    const parts = text.split(new RegExp(`(${props.searchQuery})`, 'gi'));
    return (
      <p>
        {parts.map((part, index) =>
          part.toLowerCase() === props.searchQuery.toLowerCase()
            ? <mark key={index} style={{ backgroundColor: 'yellow', color: 'black' }}>{part}</mark>
            : part
        )}
      </p>
    );
  }

  const wordCount = text.split(" ").filter((e) => e.length !== 0).length;

  return (
    <>
      <div className="container" style={{ color: props.mode === 'dark' ? 'white' : 'black' }}>
        <h1>{props.heading}</h1>
        <div className="mb-3">
          <textarea
            className="form-control"
            value={text}
            onChange={handleOnChange}
            style={{
              backgroundColor: props.mode === 'dark' ? 'grey' : 'white',
              color: props.mode === 'dark' ? 'white' : 'black'
            }}
            id="myBox"
            rows="8"
            placeholder="Enter text here..."
          ></textarea>
        </div>

        <button className="btn btn-primary mx-2 my-1" onClick={handleUpClick}>UpperCase</button>
        <button className="btn btn-primary mx-2 my-1" onClick={handleClick}>LowerCase</button>
        <button className="btn btn-success mx-2 my-1" onClick={handleCapitalize}>Capitalize</button>
        <button className="btn btn-warning mx-2 my-1" onClick={handleReverse}>Reverse Text</button>
        <button className="btn btn-danger mx-2 my-1" onClick={handleRemoveNumbers}>Remove Numbers</button>
        <button className="btn btn-secondary mx-2 my-1" onClick={handleExtraSpaces}>Remove Extra Spaces</button>
        <button className="btn btn-info mx-2 my-1" onClick={handleCopy}>Copy Text</button>
        <button className="btn btn-dark mx-2 my-1" onClick={handleClearClick}>Clear</button>
      </div>

      <div className="container my-3" style={{ color: props.mode === 'dark' ? 'white' : 'black' }}>
        <h1>Your Text Summary</h1>
        <p>{wordCount} Words | {text.length} Characters | {text.replace(/\s/g, '').length} Letters only</p>
        <p>⏱️ {(0.008 * wordCount).toFixed(2)} Minutes read</p>
        <h2>Preview</h2>
        {getHighlightedText()}
      </div>
    </>
  )
}