import React, { useState } from 'react'
import PropTypes from 'prop-types'
import { Link } from 'react-router-dom/cjs/react-router-dom.min'

export default function Navbar(props) {
  const [searchText, setSearchText] = useState('');

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchText.trim() !== '') {
      window.open(`https://www.google.com/search?q=${encodeURIComponent(searchText)}`, '_blank');
    }
  }

  const handleHighlight = () => {
    if (searchText.trim() !== '') {
      props.onSearch(searchText);
    }
  }

  return (
    <nav className={`navbar navbar-expand-lg navbar-${props.mode} bg-${props.mode}`}>
      <div className="container-fluid">
        <Link className="navbar-brand" to="/">{props.title}</Link>
        <button className="navbar-toggler" type="button" data-bs-toggle="collapse"
          data-bs-target="#navbarSupportedContent" aria-controls="navbarSupportedContent"
          aria-expanded="false" aria-label="Toggle navigation">
          <span className="navbar-toggler-icon"></span>
        </button>
        <div className="collapse navbar-collapse" id="navbarSupportedContent">
          <ul className="navbar-nav me-auto mb-2 mb-lg-0">
            <li className="nav-item">
              <Link className="nav-link active" aria-current="page" to="/">Home</Link>
            </li>
            <li className="nav-item">
              <Link className="nav-link" to="about/">{props.About}</Link>
            </li>
          </ul>

          <div className="form-check form-switch ms-auto">
            <input className="form-check-input" onClick={props.togglemode}
              type="checkbox" role="switch" id="switchCheckDefault" />
            <label className="form-check-label" htmlFor="switchCheckDefault"
              style={{ color: props.mode === 'light' ? 'black' : 'white' }}>
              Enable darkmode
            </label>
          </div>

          <form className="d-flex ms-3" role="search" onSubmit={handleSearch}>
            <input
              className="form-control me-2"
              type="search"
              placeholder="Search..."
              aria-label="Search"
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
            />
            <button className="btn btn-outline-success me-1" type="submit">Google</button>
            <button className="btn btn-outline-warning" type="button" onClick={handleHighlight}>Find</button>
          </form>
        </div>
      </div>
    </nav>
  )
}

Navbar.propTypes = { title: PropTypes.string }
